def paper_table1_target(section="Token", method="TokenCore", col_index=4):
    """Read the reference value out of the paper's own Table 1 (paper/paper.txt).

    The extracted text renders the table one cell per line, with a section header line
    ('Token' / 'Document'), then a row label per method followed by its 8 cells
    (SMS_Spam ROC/PRC, Review ROC/PRC, Grammar ROC/PRC, Average ROC/PRC).
    We therefore locate the section header, then the first occurrence of the method name
    after it, and take the 5th number (index 4 = Grammar ROC).  Nothing is hard-coded, and
    the paper file is part of the workspace, so this works on a clean re-run.  Returns None
    if the table cannot be parsed (then `pass` is reported as null rather than guessed).
    """
    path = os.path.join(ROOT, "paper", "paper.txt")
    if not os.path.exists(path):
        return None
    with open(path, encoding="utf-8", errors="replace") as f:
        lines = [ln.strip() for ln in f]
    start = next((i for i, ln in enumerate(lines) if ln.startswith("Table 1")), 0)
    try:
        i = lines.index(section, start)
    except ValueError:
        return None
    for j in range(i + 1, len(lines)):
        if lines[j] == method:
            nums, k = [], j + 1
            while len(nums) < 8 and k < len(lines):
                try:
                    nums.append(float(lines[k]))
                except ValueError:
                    pass
                k += 1
            return nums[col_index] if len(nums) == 8 else None
    return None


